  PERFORM app_session_begin((ids->>'coach.wes.u16b@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT * INTO r FROM match_award(m, 'de300000-0000-4000-8000-000000000066', $d${"version":1,"basis":"batting_bowling","factsVersion":1,"headSeq":302,"suggestions":[{"playerId":"de300000-0000-4000-8000-000000000066","figures":"27 (18) · 2/22 (3)"},{"playerId":"de300000-0000-4000-8000-000000000063","figures":"0 (1) · 2/45 (4)"},{"playerId":"de300000-0000-4000-8000-000000000069","figures":"2/28 (3.4)"}],"awardee":{"playerId":"de300000-0000-4000-8000-000000000066","figures":"27 (18) · 2/22 (3)"}}$d$::jsonb);
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The WES coach could not award Player of the Match on u16b-1029: %. Nothing was changed.', r.reason; END IF;
  PERFORM app_session_begin((ids->>'coach.kea.u16b@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT * INTO r FROM match_award(m, 'de300000-0000-4000-8000-000000000236', $d${"version":1,"basis":"batting_bowling","factsVersion":1,"headSeq":302,"suggestions":[{"playerId":"de300000-0000-4000-8000-000000000236","figures":"14 (8) · 3/37 (4)"},{"playerId":"de300000-0000-4000-8000-000000000228","figures":"9 (3) · 2/31 (4)"},{"playerId":"de300000-0000-4000-8000-000000000232","figures":"45 (27)"}],"awardee":{"playerId":"de300000-0000-4000-8000-000000000236","figures":"14 (8) · 3/37 (4)"}}$d$::jsonb);
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The KEA coach could not award Player of the Match on u16b-1029: %. Nothing was changed.', r.reason; END IF;
